import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"Q51 | 技术体系：AI全栈工程师的学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q51｜技术体系：AI全栈工程师的学习路径.md","filePath":"致程序员：AI百问百答/Q51｜技术体系：AI全栈工程师的学习路径.md","lastUpdated":1795559851000}'),n={name:"致程序员：AI百问百答/Q51｜技术体系：AI全栈工程师的学习路径.md"};function o(_,e,p,r,A,E){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="q51-技术体系-ai全栈工程师的学习路径" tabindex="-1">Q51 | 技术体系：AI全栈工程师的学习路径 <a class="header-anchor" href="#q51-技术体系-ai全栈工程师的学习路径" aria-label="Permalink to &quot;Q51 | 技术体系：AI全栈工程师的学习路径&quot;">​</a></h1><ul><li>作者介绍：彭靖田，Google Developers Expert 《深入理解 TensorFlow》作者</li></ul><p>Q：一个 AI 全栈工程师的学习路径应该是什么样的？</p><p>彭靖田：一个全栈的 AI 工程师需要掌握的技术，至少可以分成四层——应用、 平台、模型、硬件。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%B4%E7%A8%8B%E5%BA%8F%E5%91%98%EF%BC%9AAI%E7%99%BE%E9%97%AE%E7%99%BE%E7%AD%94/images/Q51/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%B4%E7%A8%8B%E5%BA%8F%E5%91%98%EF%BC%9AAI%E7%99%BE%E9%97%AE%E7%99%BE%E7%AD%94/images/Q51/1.png" alt=""></a></p><p>应用层：如上图所示 6 个常见实践场景，但也有一些企业内部的一些其他类型的应用。</p><p>平台层：有新的技术体系出来的时候，我们都可以去关注。比如，我认为 2025 年到 2030 年应该会有更多的人进入到 AI 大模型的这个赛道，所以 Dify 这种对基础门槛要求更低的技术，用拖拉拽的方式去完成 Agent 的搭建，是需要大家去了解和掌握的，包括 Dify 如何私有化部署。再比如，在国内，为了做好智能客服，我们要能够在微信生态、钉钉生态、企微生态、飞书生态等去做各种各样的客服机器人，那 LangBot 也是一个不错的项目，并且它也支持Dify。MCP 这个最近很热的一个协议。这些一个个出现的时候，我们都可以学习。</p><p>模型层：哪个大模型走的比较前沿？有哪些新的框架（比如 MoE 架构）？训练方法？DeepSeek 最新的论文你有没有了解过？如果你想在 AI 大模型这个领域按 5-10 年的发展做自己的长期规划，以后要做到技术负责人的话，这些都是你需要了解的。</p><p>算力层就不单独展开说了。</p><p>当然，这四层只是 AI 全栈技术的四层体系，要想成为技术负责人，那就不只是说纯技术的部分应该怎样去做，还得会资源协调、企业内部 AI 团队的人才组织，成为“懂原理，会落地”的复合型人才。</p>',10)])])}const I=t(n,[["render",o]]);export{c as __pageData,I as default};
